head.script:
scwin.screenId = "jldstf76120";

///////// 1. 변수 및 선언 영역 /////////

scwin.G_vertical = '\u000B';

scwin.G_formfeed = '\u000C';


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        const status = (String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "status" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("status"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "status" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("status")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "status" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("status"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "status" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("status")))));
        if ("update" === status) {
            var fn_search = $c.frame.Provider("../").fn_search;
            fn_search();
            await $c.win.alert("수정되었습니다.");
        } else {
            if ("register" === status) {
                var fn_search = $c.frame.Provider("../").fn_search;
                fn_search();
                await $c.win.alert("등록되었습니다.");
            } else {
                if ("delete" === status) {
                    var fn_search = $c.frame.Provider("../").fn_search;
                    fn_search();
                    await $c.win.alert("삭제되었습니다.");
                    $c.frame.CloseFrame();
                }
            }
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf76120.onpageload' }); }
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.editor = undefined; try { scwin.editor = /* sdd-asis-lifecycle:begin editor — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Dext5editor("dext5editor1")/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf76120' }); }

scwin.upload = undefined; try { scwin.upload = /* sdd-asis-lifecycle:begin upload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Dext5Upload("dext5upload")/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf76120' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf76120.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_update_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_update_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_update_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.update()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf76120.btn_update_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_del_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_del_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_del_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.del()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf76120.btn_del_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_frame_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_frame_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_frame_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.frame.CloseFrame()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf76120.btn_frame_onclick' }); }
};

/**
 * @method
 * @name scwin.DEXT5UPLOAD_OnCreationComplete
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.DEXT5UPLOAD_OnCreationComplete = function () {
    /* sdd-asis-lifecycle:begin DEXT5UPLOAD_OnCreationComplete — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const attachStr = "" + dma_noticeDetail.get("attachString") + "";
    if (attachStr.length > 0) {
        const temp1 = attachStr.split(scwin.G_vertical, 20);
        for (let i = 0; i < temp1.length - 1; i++) {
            const temp2 = temp1[i].split(scwin.G_formfeed, 20);
            DEXT5UPLOAD.AddUploadedFile(temp2[0], temp2[2], temp2[4], temp2[3], temp2[1], 'dext5upload');
        }
    }
    /* sdd-asis-lifecycle:end */
};



///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_dext5FileDown_ajaxsubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_dext5FileDown_ajaxsubmit = async function () {
    try { return await $c.data.downFile("/ods/dext5.do", "", ($c.util.getComponent("dma_dext5FileDownAjaxsubmitReq") ? $c.util.getComponent("dma_dext5FileDownAjaxsubmitReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name scwin.tx_load_list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/ods/dext5.do",
        ref: "dma_loadListReq",
        target: "dlt_chrgInstList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf76120.tx_load_list" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.update
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.update = async function () {
    /* sdd-asis-lifecycle:begin fn_update — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const sprtRoomtitle = $c.util.getComponent('ipt_sprtRoomtitle').getValue();
    if ($.trim(sprtRoomtitle).length == 0) {
        await $c.win.alert("제목을 입력해 주세요.");
        ($c.util.getComponent('ipt_sprtRoomtitle') && $c.util.getComponent('ipt_sprtRoomtitle').setFocus ? $c.util.getComponent('ipt_sprtRoomtitle').setFocus() : ($c.util.getComponent('ipt_sprtRoomtitle') && $c.util.getComponent('ipt_sprtRoomtitle').focus ? $c.util.getComponent('ipt_sprtRoomtitle').focus() : console.warn('[sdd] focus 대상 미해결: ipt_sprtRoomtitle')));
        return;
    }
    if (DEXT5.isEmpty("dext5editor1")) {
        await $c.win.alert("내용을 입력해 주세요.");
        DEXT5.setFocusToEditor("dext5editor1");
        return;
    }
    DEXT5UPLOAD.Transfer("dext5upload");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.DEXT5UPLOAD_OnTransfer_Complete
 * @author Inswave
 * @date 2026. 09. 29
 * @param dextId
 * @returns
 * @hidden N
*/
scwin.DEXT5UPLOAD_OnTransfer_Complete = function (dextId) {
    /* sdd-asis-lifecycle:begin DEXT5UPLOAD_OnTransfer_Complete — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const textNew = DEXT5UPLOAD.GetNewUploadListForText("dext5upload");
    if (textNew != null) {
        var rtn = fn_newTextToString(textNew);
        $('#ipt_attachFileInfo', $('#updateForm')).val(rtn);
    }
    const textDel = DEXT5UPLOAD.GetDeleteListForText("dext5upload");
    if (textDel != null) {
        var rtn = fn_delTextToString(textDel);
        $('#ipt_deleteFileInfo', $('#updateForm')).val(rtn);
    }
    $('#ipt_SCREN_ID', $('#updateForm')).val("/jldstf76120/jldstf76120.xml");
    $('#ipt_method', $('#updateForm')).val("updateSprtRoom");
    const htmlText = DEXT5.getBodyValue("dext5editor1");
    $c.util.getComponent('ipt_sprtRoomContn').setValue(htmlText);
    const notHtmlText = DEXT5.getBodyTextValue("dext5editor1");
    $c.util.getComponent('ipt_sprtRoomContnNoHtml').setValue(notHtmlText);
    $c.util.getComponent('ipt_ldMktTpCd').setValue($('#slc_selLdMktTpCd option:selected').val());
    $('#updateForm').submit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.del
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.del = async function () {
    /* sdd-asis-lifecycle:begin fn_del — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (await $c.win.confirm("삭제하시겠습니까?")) {
        $('#ipt_SCREN_ID', $('#updateForm')).val("/jldstf76120/jldstf76120.xml");
        $('#ipt_method', $('#updateForm')).val("delSprtRoom");
        $('#ipt_SCREN_PROCES_TP_CD', $('#updateForm')).val("04");
        $('#updateForm').submit();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.dext_editor_loaded_event
 * @author Inswave
 * @date 2026. 09. 29
 * @param editor
 * @returns
 * @hidden N
*/
scwin.dext_editor_loaded_event = function (editor) {
    /* sdd-asis-lifecycle:begin dext_editor_loaded_event — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    DEXT5.setHtmlValueEx($c.util.getComponent('ipt_webSprtRoomContn').getValue(), "dext5editor1");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.DEXT5UPLOAD_BeforeFileDownload
 * @author Inswave
 * @date 2026. 09. 29
 * @param uploadID strWebFile strItemKey strItemOrgName strItemUrlOrPath strLargeFiles strIsLastEvent
 * @returns
 * @hidden N
*/
scwin.DEXT5UPLOAD_BeforeFileDownload = async function (uploadID, strWebFile, strItemKey, strItemOrgName, strItemUrlOrPath, strLargeFiles, strIsLastEvent) {
    /* sdd-asis-lifecycle:begin DEXT5UPLOAD_BeforeFileDownload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let retVal = true;

    if (download_file_list === '') {
        download_file_list += strItemUrlOrPath;
        download_file_keys += strItemKey;
    } else {
        download_file_list += scwin.G_vertical + strItemUrlOrPath;
        download_file_keys += scwin.G_vertical + strItemKey;
    }
    if (strIsLastEvent == 1) {
        $c.util.getComponent('ipt_sprtRoomNoAttachSeq').setValue(download_file_keys);
        $c.util.getComponent('ipt_fileList').setValue(download_file_list);
        download_file_list = '';
        download_file_keys = '';
        await scwin.dext5FileDown();
        retVal = false;
    }
    return retVal;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.dext5FileDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.dext5FileDown = async function () {
    /* sdd-asis-lifecycle:begin dext5FileDown — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await scwin.tx_dext5FileDown_ajaxsubmit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnCallDext5
 * @author Inswave
 * @date 2026. 09. 29
 * @param result
 * @returns
 * @hidden N
*/
scwin.fnCallDext5 = async function (result) {
    /* sdd-asis-lifecycle:begin fnCallDext5 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (result.fileStatus === 'ok') {
        DEXT5UPLOAD.UPLOADTOP.G_CURRUPLOADER._config.useDownloadEvent = "0";
        DEXT5UPLOAD.DownloadFile("dext5upload");
    } else {
        await $c.win.alert("파일다운로드 중 오류가 발생하였습니다. 관리자에게 문의하시기 바랍니다.");
    }
    DEXT5UPLOAD.UPLOADTOP.G_CURRUPLOADER._config.useDownloadEvent = "1";
    /* sdd-asis-lifecycle:end */
};
